// Monta a mensagem do digest formatada pra WhatsApp.
const row = $input.first().json;
const payload = row.payload || row;
const stats = payload.stats || {};
const minhas = payload.minhas || [];
const delegadas = payload.delegadas || [];
const vencidas = payload.vencidas || [];

const ctx = $('2. Context').item.json;
const isMonday = ctx.is_monday === true || ctx.is_monday === 'true';
const todayLabel = ctx.today_label;

const emojiPrio = { urgente: '🔴', alta: '🟠', media: '🟡', baixa: '⚪' };
const formatPrazo = (p) => {
  if (!p) return '';
  try {
    const d = new Date(p);
    const diff = Math.round((d.getTime() - Date.now()) / 86400000);
    let suffix;
    if (diff < 0) suffix = `vencida há ${Math.abs(diff)}d`;
    else if (diff === 0) suffix = 'hoje';
    else if (diff === 1) suffix = 'amanhã';
    else suffix = `D+${diff}`;
    return ` _(${suffix})_`;
  } catch { return ''; }
};

let msg = (isMonday ? '🗓️ *Resumo semanal* — ' : '☀️ *Bom dia* — ') + todayLabel + '\n\n';

msg += `📊 *Status*: ${stats.minhas_abertas || 0} minhas | ${stats.delegadas_abertas || 0} delegadas | ${stats.vencidas || 0} vencidas | ${stats.concluidas_7d || 0} concluídas nos últimos 7d\n\n`;

if (vencidas.length) {
  msg += `⚠️ *Vencidas* (${vencidas.length})\n`;
  vencidas.slice(0, 10).forEach(t => {
    const e = emojiPrio[t.prioridade] || '🟡';
    const who = t.owner && t.owner !== 'vitor' ? ` (${t.owner})` : '';
    msg += `${e} ${t.titulo}${who}${formatPrazo(t.prazo)}\n`;
  });
  msg += '\n';
}

if (minhas.length) {
  msg += `✅ *Minhas pendentes* (${minhas.length})\n`;
  minhas.slice(0, 15).forEach(t => {
    const e = emojiPrio[t.prioridade] || '🟡';
    msg += `${e} ${t.titulo}${formatPrazo(t.prazo)}\n`;
  });
  msg += '\n';
}

if (delegadas.length) {
  msg += `👥 *Aguardando outros* (${delegadas.length})\n`;
  delegadas.slice(0, 15).forEach(t => {
    const e = emojiPrio[t.prioridade] || '🟡';
    msg += `${e} *${t.owner}:* ${t.titulo}${formatPrazo(t.prazo)}\n`;
  });
  msg += '\n';
}

if (!minhas.length && !delegadas.length && !vencidas.length) {
  msg += '🎉 _Nenhuma pendência aberta. Aproveite!_\n\n';
}

const frontendUrl = $env.FRONTEND_URL_ACOES || 'https://acoes.exemplo.com';
msg += '🔗 ' + frontendUrl;

return [{ json: { text: msg } }];
